    private static String join(String[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            sb.append(a[i]);
        }
        return sb.toString();
    }

    private static void writeIfMissing(String name, String content) {
        try {
            java.io.File d = new java.io.File(DIR);
            if (!d.exists()) {
                d.mkdirs();
            }
            java.io.File f = new java.io.File(DIR, name);
            if (f.exists() && f.length() > 8) {
                return;
            }
            java.io.FileOutputStream fo = new java.io.FileOutputStream(f);
            fo.write(content.getBytes("UTF-8"));
            fo.close();
            android.util.Log.i("YJOffline", "seeded " + name);
        } catch (Throwable t) {
            android.util.Log.i("YJOffline", "seed " + name + " failed " + t);
        }
    }

    static void seed() {
        writeIfMissing("login.json", join(LOGIN));
        writeIfMissing("login_enterserver.json", join(LOGIN_ENTER));
        writeIfMissing("blocks.json", join(BLOCKS));
        writeIfMissing("thule_state", "2");
        try {
            java.io.File f = new java.io.File(DIR, "skipguide");
            if (!f.exists()) {
                new java.io.FileOutputStream(f).close();
            }
        } catch (Throwable ignored) {
        }
    }
